create table if not exists template_registry.upgrade_plans (id text primary key, tenant_id text not null, environment text not null, livemode boolean not null, from_package_version_id text references template_registry.package_versions(id), to_package_version_id text not null references template_registry.package_versions(id), state template_registry.upgrade_state not null default 'announced', requested_by text not null, approved_by text, paused_reason text, rollback_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (approved_by is null or approved_by <> requested_by));
create index if not exists upgrade_plans_env_state_idx on template_registry.upgrade_plans(tenant_id,environment,livemode,state);
-- verify: select 1 from information_schema.tables where table_schema='template_registry' and table_name='upgrade_plans';
